All datasets:
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?graph ?dataset ?title WHERE {
  GRAPH ?graph {
    ?dataset a dcat:Dataset .
    OPTIONAL { ?dataset dct:title ?title }
  }
} ORDER BY ?title

Participants:
PREFIX dcat: <http://www.w3.org/ns/dcat#>
SELECT DISTINCT ?graph WHERE {
  GRAPH ?graph { ?dataset a dcat:Dataset }
}

Construction: wall datasets across repre:
PREFIX cx: <https://w3id.org/construct-dcat#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX ifc: <https://standards.buildingsmart.org/IFC/DEV/IFC4_3/OWL#>
SELECT ?graph ?dataset ?title ?representation WHERE {
  GRAPH ?graph {
    ?dataset a dcat:Dataset ;
             a ?representation ;
             cx:describesAssetType ifc:IfcWall ;
             dct:title ?title .
    VALUES ?representation { cx:BIMDataset cx:AASDataset }
  }
}

Published catalogs:
PREFIX dcat: <http://www.w3.org/ns/dcat#>
SELECT ?graph ?catalog (COUNT(DISTINCT ?dataset) AS ?datasets) WHERE {
 GRAPH ?graph {
  ?catalog a dcat:Catalog .
  OPTIONAL { ?catalog dcat:dataset/dcat:seriesMember* ?dataset . ?dataset a dcat:Dataset }
 }
} GROUP BY ?graph ?catalog

Pump 001: submodels across publishers (s:
PREFIX cx: <https://w3id.org/construct-dcat#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT DISTINCT ?graph ?catalog ?dataset ?title ?submodel ?shell ?access
WHERE {
  VALUES ?asset { <https://example.org/aas-dpp/assets/pump-001> }
  GRAPH ?graph {
    ?catalog a dcat:Catalog ; dcat:dataset ?dataset .
    ?dataset a cx:AASDataset ;
      dct:title ?title ;
      dct:subject ?asset ;
      cx:hasAASSubmodel ?submodel ;
      dcat:distribution ?distribution .
    ?submodel dct:subject ?asset ; dct:isPartOf ?shell .
    ?distribution dcat:accessURL ?access .
  }
}
ORDER BY ?catalog ?submodel
